# Look at momentum hypotheses: B and C had positive 10-step autocorr ~0.25 and 0.176
# test more: compute return autocorrs for various lags and mean reversion for A/IDX
def compute_autocorr(series, lag, horizon):
    # horizon return vs lag
    n=len(series)
    rets=[]
    for i in range(n-horizon):
        a=series[i]; b=series[i+horizon]
        if a==a and b==b and a!=0:
            rets.append((b-a))
        else:
            rets.append(float('nan'))
    x=[]; y=[]
    for i in range(len(rets)-lag):
        a=rets[i]; b=rets[i+lag]
        if a==a and b==b:
            x.append(a); y.append(b)
    if len(x)<20:
        return float('nan')
    m1=sum(x)/len(x); m2=sum(y)/len(y)
    num=0; d1=0; d2=0
    for k in range(len(x)):
        dx=x[k]-m1; dy=y[k]-m2
        num+=dx*dy; d1+=dx*dx; d2+=dy*dy
    return num/math.sqrt(d1*d2) if d1*d2>0 else 0

