# also imbalance and signed_volume predictiveness
def ic_pred(predictor, future_ret):
    xs=[]; ys=[]
    for i in range(len(predictor)):
        a=predictor[i]; b=future_ret[i] if i < len(future_ret) else float('nan')
        if a==a and b==b:
            xs.append(a); ys.append(b)
    if len(xs)<30:
        return float('nan')
    # spearman via rank? use pearson for quick
    m1=sum(xs)/len(xs); m2=sum(ys)/len(ys)
    num=0; d1=0; d2=0
    for k in range(len(xs)):
        dx=xs[k]-m1; dy=ys[k]-m2
        num+=dx*dy; d1+=dx*dx; d2+=dy*dy
    return num/math.sqrt(d1*d2) if d1*d2>0 else 0

