def ic_past_ret(asset, past_h, future_h):
    mid=H[asset]['mid']
    past=[float('nan')]*len(mid)
    fut=[float('nan')]*len(mid)
    for i in range(len(mid)):
        if i>=past_h and mid[i]==mid[i] and mid[i-past_h]==mid[i-past_h]:
            past[i]=mid[i]-mid[i-past_h]
        if i+future_h<len(mid) and mid[i]==mid[i] and mid[i+future_h]==mid[i+future_h]:
            fut[i]=mid[i+future_h]-mid[i]
    xs=[]; ys=[]
    for i in range(len(mid)):
        a=past[i]; b=fut[i]
        if a==a and b==b:
            xs.append(a); ys.append(b)
    if len(xs)<20:
        return float('nan')
    m1=sum(xs)/len(xs); m2=sum(ys)/len(ys)
    num=0; d1=0; d2=0
    for k in range(len(xs)):
        dx=xs[k]-m1; dy=ys[k]-m2
        num+=dx*dy; d1+=dx*dx; d2+=dy*dy
    return num/math.sqrt(d1*d2) if d1*d2>0 else 0

