def signal(obs):
    # C momentum: past 20 return
    c_hist = obs.hist('C','mid',30)
    if c_hist[0]!=c_hist[0] or c_hist[-1]!=c_hist[-1]:
        return {}
    past = c_hist[-1] - c_hist[-11] if len(c_hist)>=21 else 0  # approx 20 steps? hist length 30, index -1 latest, -21 is 20 ago? let's use 20
    # more precise: hist[-1] is last, hist[-21] is 20 steps ago
    try:
        past = c_hist[-1] - c_hist[-21]
    except:
        past = 0
    if past!=past:
        return {}
    # scale past to target [-1,1] with threshold ~5 cents (~1 std)
    thresh=4.0
    sig = past / thresh
    if sig>1: sig=1
    if sig<-1: sig=-1
    # flip? positive past -> long
    return {'C': float(sig)}

def signal(obs):
    # Try OIL momentum past 20 with turnover control
    hist = obs.hist('OIL','mid',50)
    if hist[0]!=hist[0]:
        return {}
    try:
        past = hist[-1] - hist[-21]
    except:
        return {}
    if past!=past:
        return {}
    thresh=5.0
    sig = past / thresh
    if sig>1: sig=1
    if sig<-1: sig=-1
    return {'OIL': float(sig), 'OIL.F': float(sig)*0.5}

def signal(obs):
    s = obs.state
    if 'hold' not in s:
        s['hold'] = {}
        s['cnt'] = {}
        s['last_target'] = {}
    out = {}
    # helper to get past return
    def past_ret(asset, n):
        try:
            h = obs.hist(asset, 'mid', n+5)
            # h[0] oldest, h[-1] latest
            if h[-1] != h[-1] or h[-n-1] != h[-n-1]:
                return None
            return float(h[-1] - h[-n-1])
        except:
            return None

    def get_target(asset, thresh, hold_steps, invert=False):
        pr = past_ret(asset, 50)
        # use 50 for most, but for bonds 50, for OIL/C 20 also works - keep 50 for stability
        cnt = s['cnt'].get(asset, 0)
        last = s['last_target'].get(asset, 0)
        if cnt > 0:
            s['cnt'][asset] = cnt - 1
            return last
        if pr is None:
            return last
        # decide
        sig = 0
        if not invert:
            if pr > thresh:
                sig = 1
            elif pr < -thresh:
                sig = -1
            else:
                sig = 0
        else:
            if pr > thresh:
                sig = -1
            elif pr < -thresh:
                sig = 1
            else:
                sig = 0
        # threshold filtering: only trade on strong signal, else stay flat to save spread
        # hold for 5 calls = 50 steps
        if sig != last:
            # if changing, require holding period
            s['hold'][asset] = sig
            s['cnt'][asset] = hold_steps
            s['last_target'][asset] = sig
            return sig
        else:
            return last

    # OIL momentum
    t = get_target('OIL', 6.0, 5, invert=False)
    out['OIL'] = float(t)
    # scale OIL.F similarly but half size to avoid double exposure
    # OIL.F highly correlated with OIL, use same signal smaller
    out['OIL.F'] = float(t * 0.6)

    # C momentum
    t2 = get_target('C', 5.0, 5, invert=False)
    out['C'] = float(t2)

    # BOND2Y mean reversion (invert)
    t3 = get_target('BOND2Y', 2.5, 5, invert=True)
    out['BOND2Y'] = float(t3)

    # BOND10Y weaker, also mean reversion but lighter
    t4 = get_target('BOND10Y', 2.5, 5, invert=True)
    out['BOND10Y'] = float(t4 * 0.5)

    # IDX vs basket arbitrage with wide band, low turnover
    try:
        a = obs.last('A','mid')
        b = obs.last('B','mid')
        c = obs.last('C','mid')
        idx = obs.last('IDX','mid')
        if a==a and b==b and c==c and idx==idx:
            basket = 0.3333*a + 0.6667*b + 0.1667*c
            diff = idx - basket
            # rolling diff stats 100
            ha = obs.hist('A','mid',100)
            hb = obs.hist('B','mid',100)
            hc = obs.hist('C','mid',100)
            hi = obs.hist('IDX','mid',100)
            diffs = []
            for i in range(100):
                ai = ha[i]; bi = hb[i]; ci = hc[i]; ii = hi[i]
                if ai==ai and bi==bi and ci==ci and ii==ii:
                    diffs.append(ii - (0.3333*ai+0.6667*bi+0.1667*ci))
            if len(diffs) >= 40:
                m = sum(diffs)/len(diffs)
                var = sum((x-m)*(x-m) for x in diffs)/len(diffs)
                std = math.sqrt(var) if var>0 else 4.0
                if std < 1.5:
                    std = 1.5
                z = (diff - m)/std
                cnt_idx = s['cnt'].get('IDX',0)
                last_idx = s['last_target'].get('IDX',0)
                if cnt_idx>0:
                    s['cnt']['IDX'] = cnt_idx-1
                    out['IDX'] = float(last_idx)
                    # hedge legs proportional
                    out['A'] = float(-last_idx*0.3333*1.2)
                    out['B'] = float(-last_idx*0.6667*1.2)
                    # C already has momentum signal, blend? keep arb separate: if arb active, override C momentum partially
                    # keep C as is if arb not active, else combine
                    if abs(last_idx) > 0.1:
                        # blend: average
                        out['C'] = float((out['C'] + (-last_idx*0.1667*1.2))/2)
                else:
                    # only trade when |z| > 1.5 to avoid spread bleed
                    target_idx = 0
                    if z > 1.5:
                        target_idx = -0.8
                    elif z < -1.5:
                        target_idx = 0.8
                    else:
                        target_idx = 0
                    if target_idx != last_idx:
                        s['cnt']['IDX'] = 4  # hold 40 steps
                        s['last_target']['IDX'] = target_idx
                        out['IDX'] = float(target_idx)
                        out['A'] = float(-target_idx*0.3333*1.2)
                        out['B'] = float(-target_idx*0.6667*1.2)
                        if abs(target_idx) > 0.1:
                            out['C'] = float((out['C'] + (-target_idx*0.1667*1.2))/2)
                    else:
                        out['IDX'] = float(last_idx)
                        out['A'] = float(-last_idx*0.3333*1.2)
                        out['B'] = float(-last_idx*0.6667*1.2)
                        if abs(last_idx) > 0.1:
                            out['C'] = float((out['C'] + (-last_idx*0.1667*1.2))/2)
            else:
                out['IDX'] = float(s['last_target'].get('IDX',0))
    except:
        pass

    # clip all to [-1,1]
    for k,v in list(out.items()):
        if v>1: out[k]=1.0
        if v<-1: out[k]=-1.0
        # round
        out[k]=float(out[k])
    return out

def signal(obs):
    s = obs.state
    if 'cnt' not in s:
        s['cnt'] = {}
        s['last'] = {}
    def get_hist(asset, n):
        try:
            h = obs.hist(asset,'mid', n+2)
            return h
        except:
            return None
    def past(asset, n):
        h = get_hist(asset, n+10)
        if h is None:
            return None
        # h[-1] latest, h[-n-1] n ago
        try:
            a = h[-1]
            b = h[-n-1]
            if a!=a or b!=b:
                return None
            return float(a-b)
        except:
            return None
    def hold_update(key, new_val, hold_steps):
        cnt = s['cnt'].get(key, 0)
        last = s['last'].get(key, None)
        if cnt>0:
            s['cnt'][key]=cnt-1
            return last
        if last is None:
            s['last'][key]=new_val
            s['cnt'][key]=hold_steps
            return new_val
        if new_val!=last:
            s['last'][key]=new_val
            s['cnt'][key]=hold_steps
            return new_val
        return last

    out={}
    # OIL: baseline long 0.6, add momentum overlay with wide threshold, hold 12 calls =120 steps
    pr_oil = past('OIL', 50)
    base_oil = 0.6
    adj_oil = 0
    if pr_oil is not None:
        if pr_oil > 10:
            adj_oil = 0.4
        elif pr_oil < -10:
            adj_oil = -0.8  # cut long to -0.2 if strong reversal
        elif pr_oil < -4:
            adj_oil = -0.4
        else:
            adj_oil = 0
    target_oil = base_oil + adj_oil
    if target_oil>1: target_oil=1
    if target_oil<-1: target_oil=-1
    target_oil = hold_update('OIL', target_oil, 12)
    out['OIL']=float(target_oil)
    out['OIL.F']=float(target_oil*0.5)

    # C: baseline long 0.5
    pr_c = past('C', 50)
    base_c = 0.5
    adj_c = 0
    if pr_c is not None:
        if pr_c > 12:
            adj_c = 0.5
        elif pr_c < -12:
            adj_c = -0.7
        elif pr_c < -6:
            adj_c = -0.3
    target_c = base_c+adj_c
    if target_c>1: target_c=1
    if target_c<-1: target_c=-1
    target_c = hold_update('C', target_c, 12)
    out['C']=float(target_c)

    # BOND2Y: small mean reversion, low size, hold 15
    pr_b2 = past('BOND2Y', 50)
    t_b2 = 0
    if pr_b2 is not None:
        if pr_b2 > 4:
            t_b2 = -0.5
        elif pr_b2 < -4:
            t_b2 = 0.5
        else:
            t_b2 = 0
    t_b2 = hold_update('BOND2Y', t_b2, 15)
    out['BOND2Y']=float(t_b2*0.5)

    # BOND10Y even smaller
    pr_b10 = past('BOND10Y', 50)
    t_b10=0
    if pr_b10 is not None:
        if pr_b10>4:
            t_b10=-0.3
        elif pr_b10<-4:
            t_b10=0.3
    t_b10 = hold_update('BOND10Y', t_b10, 15)
    out['BOND10Y']=float(t_b10)

    # Keep A,B,IDX flat unless extreme arb (very rare)
    # IDX vs basket wide band, tiny size, long hold
    try:
        a = obs.last('A','mid')
        b = obs.last('B','mid')
        c = obs.last('C','mid')
        idx = obs.last('IDX','mid')
        if a==a and b==b and c==c and idx==idx:
            basket = 0.3333*a+0.6667*b+0.1667*c
            diff = idx-basket
            ha = obs.hist('A','mid',100)
            hb = obs.hist('B','mid',100)
            hc = obs.hist('C','mid',100)
            hi = obs.hist('IDX','mid',100)
            diffs=[]
            for i in range(100):
                ai=ha[i]; bi=hb[i]; ci=hc[i]; ii=hi[i]
                if ai==ai and bi==bi and ci==ci and ii==ii:
                    diffs.append(ii-(0.3333*ai+0.6667*bi+0.1667*ci))
            if len(diffs)>=50:
                m = sum(diffs)/len(diffs)
                var = sum((x-m)*(x-m) for x in diffs)/len(diffs)
                std = math.sqrt(var) if var>0 else 4.0
                if std<2: std=2
                z=(diff-m)/std
                tidx=0
                if z>2.2:
                    tidx=-0.4
                elif z<-2.2:
                    tidx=0.4
                else:
                    tidx=0
                tidx = hold_update('IDX', tidx, 15)
                out['IDX']=float(tidx)
                out['A']=float(-tidx*0.3333)
                out['B']=float(-tidx*0.6667)
                # don't overwrite C baseline too much - blend 30%
                if abs(tidx)>0.1:
                    # blend C arb into existing C target
                    arb_c = -tidx*0.1667
                    blended = out['C']*0.7 + arb_c*0.3
                    if blended>1: blended=1
                    if blended<-1: blended=-1
                    out['C']=float(blended)
    except:
        pass

    # clip
    for k in list(out.keys()):
        v=out[k]
        if v>1: out[k]=1.0
        if v<-1: out[k]=-1.0
    return out

