def signal(obs):
    state=obs.state
    if 'targets' not in state:
        state['targets']={}
    def get_hist(asset,n):
        return obs.hist(asset,'mid',n)
    targets={}
    for asset in ['A','B','C','OIL','OIL.F']:
        hist=get_hist(asset,120)
        if hist is None or len(hist)<90:
            continue
        try:
            cur=hist[-1]
            past=hist[-81]
            if not (cur==cur and past==past and cur>0 and past>0):
                continue
            ret=(cur-past)/past
            scale=30
            raw=ret*scale
            if raw>1: raw=1
            if raw<-1: raw=-1
            if abs(raw)<0.25:
                raw=0
            prev=state['targets'].get(asset,0)
            nxt=prev*0.8 + raw*0.2
            if abs(nxt)<0.1:
                nxt=0
            targets[asset]=nxt
        except:
            continue
    try:
        hA=obs.hist('A','mid',30)
        hB=obs.hist('B','mid',30)
        hC=obs.hist('C','mid',30)
        hIDX=obs.hist('IDX','mid',30)
        if hA is not None and hB is not None and hC is not None and hIDX is not None and len(hA)>=30 and hA[-1]==hA[-1]:
            basket=0.3333*hA[-1]+0.6667*hB[-1]+0.1667*hC[-1]
            idx=hIDX[-1]
            if idx==idx and basket==basket:
                diff=idx-basket
                z=diff/25.0
                raw_idx=-z*0.4
                if raw_idx>0.5: raw_idx=0.5
                if raw_idx<-0.5: raw_idx=-0.5
                if abs(raw_idx)<0.15: raw_idx=0
                prev=state['targets'].get('IDX',0)
                nxt=prev*0.85 + raw_idx*0.15
                targets['IDX']=nxt
    except:
        pass
    state['targets']=targets.copy()
    return targets

