        for a in assets:
            h=H[a]['mid']
            imb=H[a]['imbalance']
            if t>=len(h) or h[t]!=h[t]:
                new_tgt[a]=tgt[a]
                continue
            tilt=0
            if t>=81 and h[t]==h[t] and h[t-80]==h[t-80] and h[t-80]!=0:
                r=(h[t]-h[t-80])/h[t-80]
                if abs(r)>=0.0015:
                    tt=r*mom_k1
                    if tt>0.6: tt=0.6
                    if tt<-0.6: tt=-0.6
                    tilt+=tt
            if t>=140 and h[t]==h[t] and h[t-139]==h[t-139] and h[t-139]!=0:
                r2=(h[t]-h[t-139])/h[t-139]
                if abs(r2)>=0.002:
                    tt2=r2*mom_k2
                    if tt2>0.4: tt2=0.4
                    if tt2<-0.4: tt2=-0.4
                    tilt+=tt2
            if imb[t]==imb[t]:
                v=0;cnt=0
                for k in range(5):
                    if t-k>=0 and imb[t-k]==imb[t-k]:
                        v+=imb[t-k]; cnt+=1
                if cnt>0:
                    v/=cnt
                    tilt+=v*imb_k
            if tilt>tilt_cap: tilt=tilt_cap
            if tilt<-tilt_cap: tilt=-tilt_cap
            raw=base_dict[a]+tilt
            if raw>1: raw=1
            if raw<-1: raw=-1
            prev=tgt[a]
            nxt=prev*smooth + raw*(1-smooth)
            new_tgt[a]=nxt
        # pnl for next 10 steps usando tgt (old? use new?)
        # assume we trade to new_tgt and hold for 10 steps
        for a in assets:
            h=H[a]['mid']
            # price change over next 10 steps * tgt *15 lots? just per lot
            if t+10 < len(h) and h[t+10]==h[t+10] and h[t]==h[t]:
                pnl_total+= (h[t+10]-h[t])*new_tgt[a]  # 1 lot scaling
        tgt=new_tgt
    return float(pnl_total)

