                        v+=imb[t-k]; cnt+=1
                if cnt>0:
                    v/=cnt; tilt+=v*imbk
            if tilt>cap: tilt=cap
            if tilt<-cap: tilt=-cap
            raw=base_dict[a]+tilt
            if raw>1: raw=1
            if raw<-1: raw=-1
            new_tgt[a]=tgt[a]*sm+raw*(1-sm)
        # pnl attribution to epoch of t (t//1500)
        epoch = t//1500
        if epoch>=7: epoch=6
        for a in assets:
            h=H[a]['mid']
            if t+10 < len(h) and h[t+10]==h[t+10] and h[t]==h[t]:
