def eval_cfg(bC,bOil,bOilF, bA, bBond2, bBond10, mk1, mk2, imb_k, cap, smooth):
    assets=['C','OIL','OIL.F','B','A','BOND2Y','BOND10Y']
    bases=[bC,bOil,bOilF,0.0,bA,bBond2,bBond10]
    base_dict={a:b for a,b in zip(assets,bases)}
    n=len(H['C']['mid'])
    tgt={a:base_dict[a] for a in assets}
    # fast forward to get state at start of evaluation (we need full walk)
    # instead full walk with epoch attribution more accurate: simulate full then extract last750
    pnl_total=0
    pnl_last750=0
    pnl_last1500=0
    # we will walk every 10 steps
    for t in range(140, n-10, 10):
        new_tgt={}
        for a in assets:
            h=H[a]['mid']; imb=H[a]['imbalance']
            if t>=len(h) or h[t]!=h[t]:
                new_tgt[a]=tgt[a]
                continue
            tilt=0
            if t>=81 and h[t]==h[t] and h[t-80]==h[t-80] and h[t-80]!=0:
                r=(h[t]-h[t-80])/h[t-80]
                if abs(r)>=0.0015:
                    tt=r*mk1
                    if tt>0.6: tt=0.6
                    if tt<-0.6: tt=-0.6
                    tilt+=tt
            if t>=140 and h[t]==h[t] and h[t-139]==h[t-139] and h[t-139]!=0:
                r2=(h[t]-h[t-139])/h[t-139]
                if abs(r2)>=0.002:
                    tt2=r2*mk2
                    if tt2>0.4: tt2=0.4
                    if tt2<-0.4: tt2=-0.4
                    tilt+=tt2
            if imb[t]==imb[t]:
                v=0;cnt=0
                for k in range(5):
                    if t-k>=0 and imb[t-k]==imb[t-k]:
                        v+=imb[t-k]; cnt+=1
                if cnt>0:
                    v/=cnt; tilt+=v*imb_k
            if tilt>cap: tilt=cap
            if tilt<-cap: tilt=-cap
            raw=base_dict[a]+tilt
            if raw>1: raw=1
            if raw<-1: raw=-1
            new_tgt[a]=tgt[a]*smooth+raw*(1-smooth)
        # pnl for next 10
        for a in assets:
            h=H[a]['mid']
            if t+10 < len(h) and h[t+10]==h[t+10] and h[t]==h[t]:
                contrib=(h[t+10]-h[t])*new_tgt[a]
                pnl_total+=contrib
                if t >= n-750-10:
                    pnl_last750+=contrib
                if t >= n-1500-10:
                    pnl_last1500+=contrib
        tgt=new_tgt
    return (float(pnl_total), float(pnl_last750), float(pnl_last1500))

