            for x in imb[-5:]:
                if x==x:
                    v+=x; cnt+=1
            if cnt>0:
                v/=cnt
                tilt+=v*0.15
        if h is not None and len(h)>=81 and h[-1]==h[-1] and h[-81]==h[-81] and h[-81]!=0:
            r=(h[-1]-h[-81])/h[-81]
