def signal(obs):
    out={}
    try:
        n=30
        a=obs.hist('A','mid',n); b=obs.hist('B','mid',n); c=obs.hist('C','mid',n); idx=obs.hist('IDX','mid',n)
        if len(a)<n: return out
        # smooth with mean of last 5 to reduce noise
        def sm(x):
            v=x[-5:]
            s=0.0; k=0
            for y in v:
                if y==y: s+=y; k+=1
            return s/k if k>0 else float('nan')
        ca,cb,cc,ci=sm(a),sm(b),sm(c),sm(idx)
        if not (ca==ca and cb==cb and cc==cc and ci==ci): return out
        syn=0.3333*ca+0.6667*cb+0.1667*cc
        prem=ci-syn
        T=50.0
        if prem>T:
            out['IDX']=-1.0; out['A']=-1.0; out['B']=-1.0; out['C']=-1.0
            # need hedge direction: short IDX, long basket
            out['A']=1.0; out['B']=1.0; out['C']=1.0
            out['IDX']=-1.0
        elif prem<-T:
            out['IDX']=1.0; out['A']=-1.0; out['B']=-1.0; out['C']=-1.0
        else:
            out['IDX']=0.0; out['A']=0.0; out['B']=0.0; out['C']=0.0
    except:
        pass
    return out

